  "knowledge": "Pattern Anomaly Score (PAS)",
  "description": "Measures the deviation of a trader's pattern similarity from their peer correlation, potentially indicating unique illicit behavior.",
  "definition": "PAS = |\\text{Pattern Similarity Score} - \\text{Peer Correlation Score}|"
}

{
  "id": 28,
  "knowledge": "Pattern Similarity Score Context",
  "description": "Provides context for the pattern similarity score, comparing trading to known illicit behaviors.",
  "definition": "A score from 0-1. Values near 1 indicate high similarity to known illicit trading patterns. Values near 0 indicate patterns do not strongly match known manipulative techniques."
}

{
  "id": 73,
  "knowledge": "Peer Correlation Z-Score",
  "description": "A normalized score indicating how many standard deviations an individual record's peer correlation is away from the average peer correlation of all traders within the same trader category. Used for standardized comparison across different peer groups.",
  "definition": "Z-Score = (Individual Peer Correlation - Average Peer Correlation for the Trader's Category) / Standard Deviation of Peer Correlation for the Trader's Category. The score is 0 if the standard deviation is zero or not applicable."
}

