{
  "id": 54,
  "knowledge": "Aggressive Suspicion Score (ASS)",
  "description": "Combines overall suspicious activity index with aggressive trading intensity, identifying traders who are both suspicious and trade aggressively.",
  "definition": "ASS = 'Suspicious Activity Index' \\times 'Aggressive Trading Intensity'"
}

{
  "id": 36,
  "knowledge": "Aggressive Trading Intensity (ATI)",
  "description": "Measures intensity by combining high turnover, leverage, and order modification frequency.",
  "definition": "ATI = 'Daily Turnover Rate' \\times 'Trader Leverage Exposure' \\times 'Order Modification Intensity'."
}

{
  "id": 0,
  "knowledge": "Daily Turnover Rate (DTR)",
  "description": "Calculates the ratio of a trader's daily trading volume to their account balance, indicating capital velocity.",
  "definition": "DTR = \\frac{\\text{Daily Trading Volume}}{\\text{Account Balance}}"
}

{
  "id": 2,
  "knowledge": "Trader Leverage Exposure (TLE)",
  "description": "Extracts the leverage ratio from the trader's performance data.",
  "definition": "TLE = A trader's leverage ratio, typically found within their performance metrics."
}

{
  "id": 1,
  "knowledge": "Order Modification Intensity (OMI)",
  "description": "Measures how frequently a trader modifies orders relative to their cancellation rate.",
  "definition": "OMI = \\frac{\\text{Order Modification Frequency}}{1 - \\text{Order Cancellation Percentage}} \\text{ (undefined if cancellation percentage is 1)}"
}

{
  "id": 30,
  "knowledge": "Risk-Adjusted Turnover (RAT)",
  "description": "Calculates trader turnover scaled by their leverage exposure.",
  "definition": "RAT = 'Daily Turnover Rate' \\times 'Trader Leverage Exposure'"
}

{
  "id": 37,
  "knowledge": "Suspicion-Weighted Turnover (SWT)",
  "description": "Calculates daily turnover weighted by the Suspicious Activity Index.",
  "definition": "SWT = 'Suspicious Activity Index' \\times 'Daily Turnover Rate'"
}

{
  "id": 39,
  "knowledge": "Market-Adjusted Pattern Anomaly (MAPA)",
  "description": "Calculates pattern anomaly score adjusted for market correlation, highlighting non-market related deviations.",
  "definition": "MAPA = 'Pattern Anomaly Score' \\times (1 - \\text{Market Correlation})"
}

{
  "id": 10,
  "knowledge": "High-Risk Trader Profile",
  "description": "Identifies traders exhibiting characteristics associated with high-risk trading strategies.",
  "definition": "A trader is considered High-Risk if their 'Trader Leverage Exposure' > 5.0 AND their risk level is 'Aggressive' OR their 'Daily Turnover Rate' > 0.5."
}

{
  "id": 50,
  "knowledge": "Investigation Compliance Risk Index (ICRI)",
  "description": "Combines the weighted investigation score with the inverse compliance health score, highlighting cases that are both problematic and under intense investigation.",
  "definition": "ICRI = 'Weighted Investigation Score' \\times (1 - 'Compliance Health Score')"
}

{
  "id": 33,
  "knowledge": "Weighted Investigation Score (WIS)",
  "description": "Combines raw investigation scores with the current alert severity level.",
  "definition": "WIS = 'Investigation Intensity Index' \\times A numeric multiplier based on Alert Level Severity ('Low'=1, 'High'=3, etc.)"
}

{
  "id": 6,
  "knowledge": "Investigation Intensity Index (III)",
  "description": "Combines behavioral and network analysis scores from an investigation.",
  "definition": "III = (0.6 \\times \\text{Behavioral Analysis Score}) + (0.4 \\times \\text{Network Analysis Score})"
}

{
  "id": 32,
  "knowledge": "Compliance Health Score (CHS)",
  "description": "Inverse score reflecting compliance history severity, penalizing high recidivism and poor ratings.",
  "definition": "CHS = \\frac{1}{1 + \\text{'Compliance Recidivism Score'} \\times \\text{A numeric value mapped from the 'Compliance Rating Grade'}}"
}

{
  "id": 5,
  "knowledge": "Compliance Recidivism Score (CRS)",
  "description": "Calculates a score indicating the tendency for repeat compliance issues, adjusted for account age.",
  "definition": "CRS = \\frac{\\text{Number of Previous Violations}}{\\text{Max}(1, \\frac{\\text{Account Age in Days}}{365})}"
}

{
  "id": 71,
  "knowledge": "Compliance Rating Grade",
  "description": "Explains the overall compliance assessment grade assigned in compliance cases.",
  "definition": "The compliance rating grade: 'A' represents excellent compliance; 'B' indicates good compliance with minor issues; 'C' suggests significant compliance deficiencies; 'D' signifies serious or repeated compliance failures."
}

